qexec() { qm guest exec 9010 -- /bin/bash -c "$1" 2>/dev/null | python3 -c "import json,sys; d=json.load(sys.stdin); sys.stdout.write(d.get('out-data','')); sys.stderr.write(d.get('err-data',''))"; }
export -f qexec
qexec "whoami; id; cat /etc/os-release | head -3"

